using System;

namespace StdbModule;

public static partial class EnglishQuotes
{
    public static class DavidFosterWallace
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "What if sometimes there is no choice about what to love? What if the temple comes to Mohammed? What if you just love? without deciding? You just do: you see her and in that instant are lost to sober account-keeping and cannot choose but to love?", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Severity is in the eye of the sufferer, it says. Pain is pain.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "These worst mornings with cold floors and hot windows and merciless light—the soul’s certainty that the day will have to be not traversed but sort of climbed, vertically, and then that going to sleep again at the end of it will be like falling, again, off something tall and sheer.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "That you will become way less concerned with what other people think of you when you realize how seldom they do.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "That everyone is identical in their secret unspoken belief that way deep down they are different from everyone else. That this isn't necessarily perverse.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The person in whom Its invisible agony reaches a certain unendurable level will kill herself the same way a trapped person will eventually jump from the window of a burning high-rise. Make no mistake about people who leap from burning windows. Their terror of falling from a great height is still just as great as it would be for you or me standing speculatively at the same window just checking out the view; i.e. the fear of falling remains a constant. The variable here is the other terror, the fire's flames: when the flames get close enough, falling to death becomes the slightly less terrible of two terrors. It's not desiring the fall; it's terror of the flames. Yet nobody down on the sidewalk, looking up and yelling ‘Don‘t!’ and ‘Hang on!’, can understand the jump. Not really. You'd have to have personally been trapped and felt flames to really understand a terror way beyond falling.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "That certain persons simply will not like you no matter what you do. That sleeping can be a form of emotional escape and can with sustained effort be abused. That purposeful sleep-deprivation can also be an abusable escape. That you do not have to like a person in order to learn from him/her/it. That loneliness is not a function of solitude. That logical validity is not a guarantee of truth. That it takes effort to pay attention to any one stimulus for more than a few seconds. That boring activities become, perversely, much less boring if you concentrate intently on them. That if enough people in a silent room are drinking coffee it is possible to make out the sound of steam coming off the coffee. That sometimes human beings have to just sit in one place and, like, hurt. That you will become way less concerned with what other people think of you when you realize how seldom they do. That there is such a thing as raw, unalloyed, agendaless kindness. That it is possible to fall asleep during an anxiety attack. That concentrating intently on anything is very hard work. That 99% of compulsive thinkers’ thinking is about themselves; that 99% of this self-directed thinking consists of imagining and then getting ready for things that are going to happen to them; and then, weirdly, that if they stop to think about it, that 100% of the things they spend 99% of their time and energy imagining and trying to prepare for all the contingencies and consequences of are never good. In short that 99% of the head’s thinking activity consists of trying to scare the everliving shit out of itself. That it is possible to make rather tasty poached eggs in a microwave oven. That some people’s moms never taught them to cover up or turn away when they sneeze. That the people to be the most frightened of are the people who are the most frightened. That it takes great personal courage to let yourself appear weak. That no single, individual moment is in and of itself unendurable. That other people can often see things about you that you yourself cannot see, even if those people are stupid. That having a lot of money does not immunize people from suffering or fear. That trying to dance sober is a whole different kettle of fish. That different people have radically different ideas of basic personal hygiene. That, perversely, it is often more fun to want something than to have it. That if you do something nice for somebody in secret, anonymously, without letting the person you did it for know it was you or anybody else know what it was you did or in any way or form trying to get credit for it, it’s almost its own form of intoxicating buzz. That anonymous generosity, too, can be abused. That it is permissible to want. That everybody is identical in their unspoken belief that way deep down they are different from everyone else. That this isn’t necessarily perverse. That there might not be angels, but there are people who might as well be angels.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Hal, who's empty but not dumb, theorizes privately that what passes for hip cynical transcendence of sentiment is really some kind of fear of being really human, since to be really human (at least as he conceptualizes it) is probably to be unavoidably sentimental and naïve and goo-prone and generally pathetic, is to be in some sort of basic interior way forever infantile, some sort of not-quite-right-looking infant dragging itself anclitically around the map, with big wet eyes and froggy-soft skin, huge skull, goey drool. One of the really American things about Hal, probably, is the way he despises what it is he's really lonely for: this hideous internal self, incontinent of sentiment and need, that pules and writhes just under the hip empty mask, anhedonia.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The idea was to have the accident and whatever explosion and fire was involved occur someplace isolated enough that no one else would see it, so that there would be as little an aspect of performance to the thing as I could manage and no temptation to spend my last few seconds trying to imagine what impressions the sight and sound of the impact might make on someone watching. I was partly concerned that it might be spectacular and dramatic and might look as if the driver was trying to go out in as dramatic a way as possible. This is the sort of shit we waste our lives thinking about.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "A large percentage of bright young men and women locate the impetus behind their career choice in the belief that they are fundamentally different from the common run of man, unique and in certain crucial ways superior, more as it were central, meaningful—what else could explain the fact that they themselves have been at the exact center of all they've experienced for the whole 20 years of their conscious lives?—and that they can and will make a difference in their chosen field simply by the fact of their unique and central presence to it...", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "We all have our little solipsistic delusions, ghastly intuitions of utter singularity: that we are the only one in the house who ever fills the ice-cube tray, who unloads the clean dishwasher, who occasionally pees in the shower, whose eyelid twitches on first dates; that only we take casualness terribly seriously; that only we fashion supplication into courtesy; that only we hear the whiny pathos in a dog's yawn, the timeless sigh in the opening of the hermetically-sealed jar, the splattered laugh in the frying egg, the minor-D lament in the vacuum's scream; that only we feel the panic at sunset the rookie kindergartner feels at his mother's retreat. That only we love the only-we. That only we need the only-we. Solipsism binds us together, J.D. knows. That we feel lonely in a crowd; stop not to dwell on what's brought the crowd into being. That we are, always, faces in a crowd.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "To be just a little less arrogant. To have just a little critical awareness about myself and my certainties. Because a huge percentage of the stuff that I tend to be automatically certain of is, it turns out, totally wrong and deluded.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The really important kind of freedom involves attention, and awareness, and discipline, and effort, and being able truly to care about other people and to sacrifice for them, over and over, in myriad petty little unsexy ways, every day.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "That is real freedom. That is being educated, and understanding how to think. The alternative is unconsciousness, the default setting, the rat race, the constant gnawing sense of having had, and lost, some infinite thing.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "And I submit that this is what the real, no-shit value of your liberal arts education is supposed to be about. How to keep from going through your comfortable, prosperous, respectable adult life dead, unconscious, a slave to your head and to your natural default setting of being uniquely, completely, imperially alone, day in and day out.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The American Academy of Emergency Medicine confirms it: Each year, between one and two dozen adult US males are admitted to ERs after having castrated themselves. With kitchen tools, usually sometimes wire cutters. In answer to the obvious question, surviving patients most often report that their sexual urges had become a source of intolerable conflict and anxiety. The desire for perfect release and the real-world impossibility of perfect, whenever-you-want-it release had together produced a tension they could no longer stand.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "A city that pretends to be nothing but what it is, an enormous machine of exchange - of spectacle for money, of sensation for money, of money for more money, of pleasure for whatever be tomorrow's abstract cost.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "In Caesars Palace is America conceived as a new kind of Rome: conqueror of its own people. An empire of self.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Not unlike urban gangs, police, carnival workers and certain other culturally marginalized guilds, the US porn industry is occluded and insular in a way that makes it seem like high school.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "It is difficult to describe how it feels to gaze at living human beings whom you’ve seen perform in hard-core porn. To shake the hand of a man whose precise erectile size, angle, and vasculature are known to you. That strange I-think-we’ve-met-before sensation one feels upon seeing any celebrity in the flesh is here both intensified and twisted. It feels intensely twisted to see reigning industry queen Jenna Jameson chilling out at the Vivid booth in Jordaches and a latex bustier and to know already that she has a tattoo of a sundered valentine with the tagline HEART BREAKER on her right buttock and a tiny hairless mole just left of her anus.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "So much about today’s adult industry seems like an undeft parody of Hollywood and the nation writ large. The top performers are comic-book caricatures of sexual allure. The prosthetic breasts and lifted buttocks and (no kidding) artificial cheekbones are nothing more than accentuations of a mentality that yields huge liposuction and collagen industries. The gynecologically explicit sexuality of Jenna, Jasmin, et al. seems more than anything like a Mad magazine spoof of the “smoldering” sexuality of Sharon Stone and Madonna and so many other mainstream iconettes.Not to mention the fact that the adult industry takes many of the psychological deformities that Hollywood is famous for—the vanity, the vulgarity, the rank commercialism—and not only makes them overt and grotesque but seems then to revel in that grotesquerie.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Past the flannel plains and blacktop graphs and skylines of canted rust, and past the tobacco-brown river overhung with weeping trees and coins of sunlight through them on the water downriver, to the place beyond the windbreak, where untilled fields simmer shrilly in the A.M. heat: shattercane, lamb’s-quarter, cutgrass, sawbrier, nutgrass, jimsonweed, wild mint, dandelion, foxtail, muscadine, spinecabbage, goldenrod, creeping charlie, butter-print, nightshade, ragweed, wild oat, vetch, butcher grass, invaginate volunteer beans, all heads gently nodding in a morning breeze like a mother’s soft hand on your cheek. An arrow of starlings fired from the windbreak’s thatch. The glitter of dew that stays where it is and steams all day. A sunflower, four more, one bowed, and horses in the distance standing rigid and still as toys. All nodding. Electric sounds of insects at their business. Ale-colored sunshine and pale sky and whorls of cirrus so high they cast no shadow. Insects all business all the time. Quartz and chert and schist and chondrite iron scabs in granite. Very old land. Look around you. The horizon trembling, shapeless. We are all of us brothers.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The next suitable person you’re in light conversation with, you stop suddenly in the middle of the conversation and look at the person closely and say, “What’s wrong?” You say it in a concerned way. He’ll say, “What do you mean?” You say, “Something’s wrong. I can tell. What is it?” And he’ll look stunned and say, “How did you know?” He doesn’t realize something’s always wrong, with everybody. Often more than one thing. He doesn’t know everybody’s always going around all the time with something wrong and believing they’re exerting great willpower and control to keep other people, for whom they think nothing’s ever wrong, from seeing it.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Maybe it's not metaphysics. Maybe it's existential. I'm talking about the individual US citizen's deep fear, the same basic fear that you and I have and that everybody has except nobody ever talks about it except existentialists in convoluted French prose. Or Pascal. Our smallness, our insignificance and mortality, yours and mine, the thing that we all spend all our time not thinking about directly, that we are tiny and at the mercy of large forces and that time is always passing and that every day we've lost one more day that will never come back and our childhoods are over and our adolescence and the vigor of youth and soon our adulthood, that everything we see around us all the time is decaying and passing, it's all passing away, and so are we, so am I, and given how fast the first forty-two years have shot by it's not going to be long before I too pass away, whoever imagined that there was a more truthful way to put it than \"die,\" \"pass away,\" the very sound of it makes me feel the way I feel at dusk on a wintry Sunday--... And not only that, but everybody who knows me or even knows I exist will die, and then everybody who knows those people and might even conceivably have even heard of me will die, and so on, and the gravestones and monuments we spend money to have pour in to make sure we're remembered, these'll last what-- a hundred years? two hundred?-- and they'll crumble, and the grass and insects my decomposition will go to feed will die, and their offspring, or if I'm cremated the trees that are nourished by my windblown ash will die or get cut down and decay, and my urn will decay, and that before maybe three of four generations it will be like I never existed, not only will I have passed away but it will be like I was never here, and people in 2104 or whatever will no more think of Stuart A. Nichols Jr. than you or I think of John T. Smith, 1790 to 1864, of Livingston, Virginia, or some such. That everything is on fire, slow fire, and we're all less than a million breaths away from an oblivion more total than we can even bring ourselves to even try to imagine, in fact, probably that's why the manic US obsession with production, produce, produce, impact the world, contribute, shape things, to help distract us from how little and totally insignificant and temporary we are... The post-production capitalist has something to do with the death of civics. But so does fear of smallness and death and everything being on fire.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Routine, repetition, tedium, monotony, ephemeracy, inconsequence, abstraction, disorder, boredom, angst, ennui—these are the true hero’s enemies, and make no mistake, they are fearsome indeed. For they are real.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Every love story is a ghost story.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "How odd I can have all this inside me and to you it’s just words.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The assumption that everyone else is like you. That you are the world. The disease of consumer capitalism. The complacent solipsism.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Since we all breathe, all the time, it is amazing what happens when someone else directs you how and when to breathe. And how vividly someone with no imagination whatsoever can see what he’s told is right there, complete with banister and rubber runners, curving down and rightward into a darkness that recedes before you.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Tax Law is like the world's biggest chess game with all sorts of weird conundrums about ethics and civics and consent of the governed built in. For me, it's a bit like math. I have no talent for it but find it still erotically interesting.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "We're all—especially those of us who are educated and have read a lot and have watched TV critically—in a very self-conscious and sort of worldly and sophisticated time, but also a time when we seem terribly afraid of other people's reactions to us and very desperate to control how people interpret us. Everyone is extremely conscious of manipulating how they come off in the media; they want to structure what they say so that the reader or audience will interpret it in the way that is most favorable to them. What's interesting to me is that this isn't all that new. This was the project of the Sophists in Athens, and this is what Socrates and Plato thought was so completely evil. The Sophists had this idea: Forget this idea of what's true or not—what you want to do is rhetoric; you want to be able to persuade the audience and have the audience think you're smart and cool. And Socrates and Plato, basically their whole idea is, \"Bullshit. There is such a thing as truth, and it's not all just how to say what you say so that you get a good job or get laid, or whatever it is people think they want.\"", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "I felt despair. The word’s overused and banalified now, despair, but it’s a serious word, and I’m using it seriously. For me it denotes a simple admixture — a weird yearning for death combined with a crushing sense of my own smallness and futility that presents as a fear of death. It’s maybe close to what people call dread or angst. But it’s not these things, quite. It’s more like wanting to die in order to escape the unbearable feeling of becoming aware that I’m small and weak and selfish and going without any doubt at all to die. It’s wanting to jump overboard.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "An ad that pretends to be art is — at absolute best — like somebody who smiles warmly at you only because he wants something from you. This is dishonest, but what's sinister is the cumulative effect that such dishonesty has on us: since it offers a perfect facsimile or simulacrum of goodwill without goodwill's real spirit, it messes with our heads and eventually starts upping our defenses even in cases of genuine smiles and real art and true goodwill. It makes us feel confused and lonely and impotent and angry and scared. It causes despair.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "There is something inescapably bovine about an American tourist in motion as part of a group. A certain greedy placidity about them. Us, rather. In port we automatically become Peregrinator americanusy Die Lumpenamerikaner. The Ugly Ones.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "How long has it been since you did Absolutely Nothing? I know exactly how long it's been for me. I know how long it's been since I had every need met choicelessly from someplace outside me, without my having to ask or even acknowledge that I needed. And that time I was floating, too, and the fluid was salty, and warm but not too-, and if I was conscious at all I'm sure I felt dreadless, and was having a really good time, and would have sent postcards to everyone wishing they were here.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The emergence of something called Metafiction in the American '60s was hailed by academic critics as a radical aesthetic, a whole new literary form, literature unshackled from the cultural cinctures of mimetic narrative and free to plunge into reflexivity and self-conscious meditations on aboutness. Radical it may have been, but thinking that postmodern Metafiction evolved unconscious of prior changes in readerly taste is about as innocent as thinking that all those college students we saw on television protesting the Vietnam war were protesting only because they hated the Vietnam war (They may have hated the war, but they also wanted to be seen protesting on television. TV was where they'd seen the war, after all. Why wouldn't they go about hating it on the very medium that made their hate possible?) Metafictionists may have had aesthetic theories out the bazoo, but they were also sentient citizens of a community that was exchanging an old idea of itself as a nation of do-ers and be-ers for a new vision of the U.S.A. as an atomized mass of self-conscious watchers and appearers. For Metafiction, in its ascendant and most important phases, was really nothing more than a single-order expansion of its own theoretical nemesis, Realism: if Realism called it like it saw it, Metafiction simply called it as it saw itself seeing it. This high-cultural postmodern genre, in other words, was deeply informed by the emergence of television and the metastasis of self-conscious watching.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "And I'm not saying that television is vulgar and dumb because the people who compose Audience are vulgar and dumb. Television is the way it is simply because people tend to be extremely similar in their vulgar and prurient and dumb interests and wildly different in their refined and aesthetic and noble interests.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "And make no mistake: irony tyrannizes us. The reason why our pervasive cultural irony is at once so powerful and so unsatisfying is that an ironist is impossible to pin down. All U.S. irony is based on an implicit \"I don’t really mean what I’m saying.\" So what does irony as a cultural norm mean to say? That it’s impossible to mean what you say? That maybe it’s too bad it’s impossible, but wake up and smell the coffee already? Most likely, I think, today’s irony ends up saying: \"How totally banal of you to ask what I really mean.\"", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "So then how have irony, irreverence, and rebellion come to be not liberating but enfeebling in the culture today’s avant-garde tried to write about? One clue’s to be found in the fact that irony is still around, bigger than ever after 30 long years as the dominant mode of hip expression. It’s not a rhetorical mode that wears well. As [Lewis] Hyde. . .puts it, \"Irony has only emergency use. Carried over time, it is the voice of the trapped who have come to enjoy the cage.\" This is because irony, entertaining as it is, serves an almost exclusively negative function. It’s critical and destructive, a ground-clearing. Surely this is the way our postmodern fathers saw it. But irony’s singularly unuseful when it comes to constructing anything to replace the hypocrisies it debunks. This is why Hyde seems right about persistent irony being tiresome. It is unmeaty. Even gifted ironists work best in sound bites. I find gifted ironists sort of wickedly funny to listen to at parties, but I always walk away feeling like I’ve had several radical surgical procedures. And as for actually driving cross-country with a gifted ironist, or sitting through a 300-page novel full of nothing by trendy sardonic exhaustion, one ends up feeling not only empty but somehow. . .oppressed.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "[W]e prefer not to countenance the kinds of sacrifices the professional-grade athlete has made to get so good at one particular thing. . . . We prefer not to consider the shockingly vapid and primitive comments uttered by athletes in postcontest interviews, or to imagine what impoverishments in one's mental life would allow people actually to think in the simplistic way great athletes seem to think. Note the way \"up-close and personal profiles\" of professional athletes strain so hard to find evidence of rounded human life—outside interests and activities, charities, values beyond the sport. We ignore what's obvious, that most of this straining is farce. It's farce because the realities of top-level athletics today require an early and total commitment to one pursuit. An almost ascetic focus. A subsumption of almost all other features of human life to their one chosen talent and pursuit. A consent to life in a world that, like a child's world, is very serious and very small.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Beauty is not the goal of competitive sports, but high-level sports are a prime venue for the expression of human beauty. The relation is roughly that of courage to war. The human beauty we’re talking about here is beauty of a particular type; it might be called kinetic beauty. Its power and appeal are universal. It has nothing to do with sex or cultural norms. What it seems to have to do with, really, is human beings’ reconciliation with the fact of having a body.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "It's hard to get good answers to why Young Voters are so uninterested in politics. This is probably because it's next to impossible to get someone to think hard about why he's not interested in something. The boredom itself preempts inquiry; the fact of the feeling's enough. Surely one reason, though, is politics is not cool. Or say rather that cool, interesting, alive people do not seem to be the ones who are drawn to the Political Process. Think back to the sort of kids in high school or college who were into running for student office: dweeby, overgroomed, obsequious to authority, ambitious in a sad way. Eager to play the Game. The kind of kids other kids would want to beat up if it didn't seem so pointless and dull. And now consider some of 2000's adult versions of these very same kids . . . Men who aren't enough like human beings even to dislike—what one feels when they loom into view is just an overwhelming lack of interest, the sort of deep disengagement that is so often a defense against pain. Against sadness. In fact the likeliest reason why so many of us care so little about politics is that modern politicians make us sad, hurt us in ways that are hard even to name, much less to talk about. It's way easier to roll your eyes and not give a shit. You probably don't want to hear about all this, even.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Can the decision to be less selfish ever be anything other than a selfish decision?", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "If you are bored and disgusted by politics and don't bother to vote, you are in effect voting for the entrenched Establishments of the two major parties, who please rest assured are not dumb, and who are keenly aware that it is in their interests to keep you disgusted and bored and cynical and to give you every possible psychological reason to stay at home doing one-hitters and watching MTV on primary day. By all means stay home if you want, but don't bullshit yourself that you're not voting. In reality, there is no such thing as not voting: you either vote by voting, or you vote by staying home and tacitly doubling the value of some Diehard's vote.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "I had a teacher I liked who used to say good fiction’s job was to comfort the disturbed and disturb the comfortable.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "In ways that certain of us are uncomfortable about, SNOOTs' attitudes about contemporary usage resemble religious/political conservatives' attitudes about contemporary culture: We combine a missionary zeal and a near-neural faith in our beliefs' importance with a curmudgeonly hell-in a-handbasket despair at the way English is routinely manhandled and corrupted by supposedly educated people. The Evil is all around us: boners and clunkers and solecistic howlers and bursts of voguish linguistic methane that make any SNOOT's cheek twitch and forehead darken. A fellow SNOOT I know likes to say that listening to most people's English feels like watching somebody use a Stradivarius to pound nails. We are the Few, the Proud, the Appalled at Everyone Else.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "A Democratic Spirit is one that combines rigor and humility, i.e., passionate conviction plus sedulous respect for the convictions of others. As any American knows, this is a very difficult spirit to cultivate and maintain, particularly when it comes to issues you feel strongly about. Equally tough is a D.S.'s criterion of 100 percent intellectual integrity—you have to be willing to look honestly at yourself and your motives for believing what you believe, and do it more or less continually.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Almost anyone who loves tennis and follows the men's tour on television has, over the last few years, had what might be termed Federer moments. These are times, watching the young Swiss at play, when the jaw drops and eyes protrude and sounds are made that bring spouses in from other rooms to see if you're OK", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Ten o'clock to one qualifies as late at night in southern California, where hardly anything reputable's open after nine.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The fact of the matter is that it is not John Ziegler's job to be responsible, or nuanced, or to think about whether his on-air comments are productive or dangerous, or cogent, or even defensible. That is not to say that the host would not defend his \"we're better”—strenuously—or that he does not believe it's true. It is to say that he has exactly one on-air job, and that is to be stimulating.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "KFI's John Ziegler is not a journalist — he is an entertainer. Or maybe it's better to say that he is part of a peculiar, modern, and very popular type of news industry, one that manages to enjoy the authority and influence of journalism without the stodgy constraints of fairness, objectivity, and responsibility that make trying to tell the truth such a drag for everyone involved. It is a frightening industry, though not for any of the simple reasons most critics give.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "In some respects all this variety is probably good, productive of difference and dialogue and so on. But it can also be confusing and stressful for the average citizen. Short of signing on to a particular mass ideology and patronizing only those partisan news sources that ratify what you want to believe, it is increasingly hard to determine which sources to pay attention to and how exactly to distinguish real information from spin.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Whatever the social effects of talk radio or the partisan agendas of certain hosts, it is a fallacy that political talk radio is motivated by ideology. It is not. Political talk radio is a business, and it is motivated by revenue. The conservatism that dominates today's AM airwaves does so because it generates high Arbitron ratings, high ad rates, and maximum profits.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "For obvious reasons, critics of political talk radio concern themselves mainly with the programs' content. Talk station management, on the other hand, tends to think of content as a subset of personality, of how stimulating a given host is.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Hosting talk radio is an exotic, high-pressure gig that not many people are fit for, and being truly good at it requires skills so specialized that many of them don't have names.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "KFI's spot load is an instance of the kind of multivariable maximization problem that M.B.A. programs thrive on. It is obviously in the station's financial interest to carry just as high a volume of ads as it can without hurting ratings—the moment listeners begin turning away from KFI because of too many commercials, the Arbitron numbers go down, the rates charged for ads have to be reduced, and profitability suffers.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "It is, after all, unlikely that Rush Limbaugh always feels as jaunty and confident as he seems on the air, or that Howard Stern really is deeply fascinated by porn starlets every waking minute of the day. But a host's persona is not the same as outright acting. For the most part, it's probably more like the way we are all slightly different with some people than we are with others.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Because of the Fairness Doctrine, talk stations had to hire and program symmetrically: if you had a three-hour program whose host's politics were on one side of the ideological spectrum, you had to have another long-form program whose host more or less spoke for the other side. Weirdly enough, up through the mid-eighties it was usually the U.S. right that benefited most from the Doctrine.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "The Fairness Doctrine's repeal was part of the sweeping deregulations of the Reagan era, which aimed to liberate all sorts of industries from government interference and allow them to compete freely in the marketplace. The old, Rooseveltian logic of the Doctrine had been that since the airwaves belonged to everyone, a license to profit from those airwaves conferred on the broadcast industry some special obligation to serve the public interest. Commercial radio broadcasting was not, in other words, originally conceived as just another for-profit industry; it was supposed to meet a higher standard of social responsibility.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Compared with many talk-radio hosts, John Ziegler is unusually polite to on-air callers. Which is to say that he doesn't yell at them, call them names, or hang up while they're speaking, although he does get frustrated with some calls. But there are good and bad kinds of frustration, stimulation-wise. Hence the delicate art of call screening.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "Overall, the layout and myriad tactical functions of the prep room are too complicated to try to describe this late in the game. At one end, it gives on to the KFI newsroom, which is a whole galaxy unto itself. At the other, comparatively uncluttered end is a set of thick, distinguished-looking doors leading off into the offices of the Station Manager, Director of Marketing & Promotions, Program Director, and so on, with also a semi-attached former closet for the P.D.'s assistant, a very kindly and eccentric lady who's been at KFI for over twenty years and wears a high-tech headset that one begins, only over time, to suspect isn't really connected to anything.", Author = "David Foster Wallace" },
            new Quote { Id = "https://en.wikiquote.org/wiki/David_Foster_Wallace", Text = "I had kind of a midlife crisis at twenty which probably doesn’t augur well for my longevity.", Author = "David Foster Wallace" },
        };
    }
}